// Etsy begrenzt den Zeitraum je Ledger-Abfrage → Zeitraum seit dem letzten
// gespeicherten Eintrag bis jetzt in 21-Tage-Fenster aufteilen.
// Vorher wurde nur EIN Fenster abgefragt: war es leer (Urlaubsmodus, ruhige
// Wochen), stand der Sync dauerhaft still, weil MAX(date) nie weiterlief.
const WINDOW = 21 * 86400;
const cfg = $input.first().json;
const now = Math.floor(Date.now() / 1000);

const windows = [];
for (let from = Number(cfg.last_sync_ts); from < now; from += WINDOW) {
  windows.push({
    json: {
      api_key:     cfg.api_key,
      shop_id:     cfg.shop_id,
      min_created: from,
      max_created: Math.min(from + WINDOW, now),
    },
  });
}
return windows;

// Etsy Ledger-Entry → etsy_transactions-Schema
// Doku: https://developers.etsy.com/documentation/reference#operation/getShopPaymentAccountLedgerEntries
//
// ledger_type-Werte aus echten API-Responses sind gemischt-case;
// daher hier lowercased mappen.
const ENTRY_TYPE_MAP = {
  'payment_gross':          'sale',            // Zahlung des Käufers, BRUTTO inkl. VAT (s.u.)
  'transaction':            'fee_transaction', // Etsy-Transaktionsgebühr
  'renew_sold_auto':        'fee_listing',     // Listing-Verlängerung nach Verkauf
  'renew_sold':             'fee_listing',
  'renew_auto':             'fee_listing',
  'renew_expired':          'fee_listing',     // Verlängerung abgelaufener Listings
  'auto_renew_expired':     'fee_listing',
  'listing':                'fee_listing',
  'offsite_ads_fee':        'fee_ads',
  'payment_processing_fee': 'fee_processing',
  'refund':                 'refund',
  // Steuern, die Etsy als Plattform ('deemed supplier') vom Käufer erhebt und
  // selbst abführt – kein Umsatz des Shops. Sie stecken bereits im Betrag von
  // PAYMENT_GROSS ('sale') und werden hier als Minus-Zeile wieder abgezogen.
  // Umsatz netto = Summe aus 'sale' UND 'marketplace_tax'. Die
  // marketplace_tax-Zeilen also NICHT herausfiltern, sonst enthält der
  // Umsatz die VAT.
  'sales_tax':              'marketplace_tax', // US marketplace facilitator tax
  'vat_tax_ep':             'marketplace_tax', // VAT auf digitale Artikel (electronic platform)
  // Geldbewegungen ohne Ertrag/Aufwand
  'disburse':               'payout',          // Auszahlung aufs Bankkonto
  'disburse2':              'payout',
  'billing_payment':        'transfer',        // Karte belastet, um negativen Saldo auszugleichen
};

// Pro Zeitfenster und Seite kommt ein eigenes Item – alle einsammeln.
// Fenstergrenzen sind inklusiv, daher doppelte entry_ids verwerfen.
const seen = new Set();
const results = $input.all()
  .flatMap(i => i.json.results ?? [])
  .filter(e => !seen.has(e.entry_id) && seen.add(e.entry_id));

// Buchungsmonat in deutscher Zeit (UTC würde Einträge vom Monatsletzten
// nach 22/23 Uhr dem falschen Monat zuordnen).
const berlinMonth = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit',
});

return results.map(entry => {
  // Etsy liefert Beträge in Cents → in EUR umrechnen
  const toEur = (v) => v != null ? (v / 100) : null;

  const rawType = (entry.ledger_type ?? '').toLowerCase();
  // Unbekannte Typen nicht raten (früher: 'fee_transaction', dadurch wurden
  // z.B. Kartenbelastungen und Listing-Gebühren falsch summiert), sondern als
  // 'other' sichtbar machen. ledger_type bleibt gespeichert; nach einer
  // Ergänzung der Map korrigiert der nächste Abruf des Eintrags den Typ.
  const type = ENTRY_TYPE_MAP[rawType] ?? 'other';

  // order_id: reference_id zeigt nur dann auf eine Bestellung,
  // wenn reference_type === 'receipt'. Bei 'transaction',
  // 'processing_fee', 'listing', 'disbursement', 'shop_payment',
  // 'etsy' zeigt es auf andere Entitäten → null.
  const orderId = entry.reference_type === 'receipt' && entry.reference_id
    ? String(entry.reference_id)
    : null;

  const amount = toEur(entry.amount);
  const date   = new Date(entry.create_date * 1000).toISOString();
  const month  = berlinMonth.format(new Date(date)); // '2026-04'

  return {
    json: {
      transaction_id: String(entry.entry_id),
      order_id:       orderId,
      type,
      ledger_type:    entry.ledger_type ?? null,
      reference_type: entry.reference_type ?? null,
      reference_id:   entry.reference_id != null ? String(entry.reference_id) : null,
      description:    entry.description ?? null,
      amount,
      fee_amount:     null,  // Ledger API hat keine separate Fee pro Zeile
      net_amount:     amount,
      currency:       entry.currency ?? 'EUR',
      date,
      month,
    }
  };
});
